def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            top = min(y for y, x in cells)
            left = min(x for y, x in cells)
            bottom = max(y for y, x in cells)
            shape = {(y-top, x-left) for y, x in cells}
            comps.append((top, left, bottom-top+1, color, shape))

    out = [[0] * w for _ in range(h)]
    for top, left, sh, color, shape in comps:
        # Components are brought to the nearest horizontal edge.
        y0 = 0 if top < h // 3 else h - sh
        for dy, dx in shape:
            if 0 <= y0 + dy < h and 0 <= left + dx < w:
                out[y0 + dy][left + dx] = color
    return out
